CREATE TABLE `SeatLock` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `show_id` int NOT NULL,
  `seat_id` int NOT NULL,
  `expires_at` datetime(3) NOT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `SeatLock_show_id_seat_id_key` (`show_id`,`seat_id`),
  KEY `SeatLock_expires_at_idx` (`expires_at`),
  KEY `SeatLock_user_id_idx` (`user_id`),
  KEY `SeatLock_show_id_idx` (`show_id`),
  KEY `SeatLock_seat_id_fkey` (`seat_id`),
  CONSTRAINT `SeatLock_seat_id_fkey` FOREIGN KEY (`seat_id`) REFERENCES `Seat` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `SeatLock_show_id_fkey` FOREIGN KEY (`show_id`) REFERENCES `Show` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `SeatLock_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `User` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
